function MatPane({ T, m }) {
  return <PPane style={{ padding: 0 }}>
    <div style={{ display: 'flex', gap: 4, padding: 8, background: T.bg2 }}><Swatch m={m} w={150} h={112} r={12} /><div style={{ flex: 1, display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 4 }}>{[m.lastIn, '12/08/26'].map((d, i) => <span key={i} style={{ position: 'relative', borderRadius: 8, overflow: 'hidden' }}><Swatch m={m} w="100%" h={54} r={8} style={{ width: '100%', filter: i ? 'saturate(.8)' : 'none' }} /><span style={{ position: 'absolute', left: 4, bottom: 3, fontFamily: T.fontUI, fontSize: 9, color: '#fff', textShadow: '0 1px 2px rgba(0,0,0,.6)' }}>lot {d.slice(0, 5)}</span></span>)}<span className="press" style={{ borderRadius: 8, border: `1px dashed ${T.line2}`, display: 'grid', placeItems: 'center', color: T.ink3 }}><Ic name="camera" size={14} /></span><span className="press" style={{ borderRadius: 8, background: T.chipBg, display: 'grid', placeItems: 'center', fontFamily: T.fontUI, fontSize: 9.5, color: T.ink2, textAlign: 'center', padding: 4 }}>use on job cards</span></div></div>
    <div style={{ padding: '10px 14px 14px', flex: 1, minHeight: 0, overflow: 'hidden', display: 'flex', flexDirection: 'column' }}>
      <Meta T={T} style={{ display: 'block', marginBottom: 4 }}>photo stand-ins · lot photos from inward land here · primary set in Studio</Meta>
      <div style={{ display: 'flex', alignItems: 'baseline', gap: 8 }}><span style={{ fontFamily: T.fontDisplay, fontSize: 22, fontWeight: 600 }}>{m.name}</span><span style={{ display: 'inline-flex', alignItems: 'center', gap: 5, fontFamily: T.fontUI, fontSize: 12.5, color: T.ink2 }}><span style={{ width: 10, height: 10, borderRadius: 3, background: prShade(m.shade) }} />{m.shade}</span><span style={{ flex: 1 }} /><StockWord T={T} m={m} /></div>
      <Meta T={T} style={{ display: 'block', marginTop: 2 }}>{m.code} · {m.group} · {m.unit} · {m.dye ? m.dye.dyer : m.sup} · {m.city}{m.barcode !== false && ' · barcode 8901 2345'}</Meta>
      <div style={{ display: 'flex', gap: 8, marginTop: 10 }}><T.Kpi label="On hand" value={`${m.stock} ${m.unit}`} small tone={m.out ? 'danger' : undefined} /><T.Kpi label="On order" value={m.order ? `${m.order} ${m.unit}` : '—'} small /><T.Kpi label="Consumed · month" value={`${m.consumed || Math.round(m.stock * .4)} ${m.unit}`} small /></div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginTop: 8, fontFamily: T.fontUI, fontSize: 11.5, color: T.ink2 }}><Ic name="bell" size={12} color={T.ink3} />{m.reorder ? <span>Reorder level {m.reorder} {m.unit} · <span className="press" style={{ color: T.accent }}>edit</span></span> : <span>No reorder level yet · <span className="press" style={{ color: T.accent }}>set one</span> · Low shows only with a level</span>}<span style={{ flex: 1 }} /><span>Rate avg ₹{m.price || '—'}<Lock T={T} /></span></div>
      {m.dye && <div style={{ marginTop: 8, padding: '8px 10px', borderRadius: 12, background: T.accentSoft, fontFamily: T.fontUI, fontSize: 11.5, color: T.ink2 }}><b style={{ color: T.ink }}>Lineage</b> · {m.dye.from} → {m.dye.dyer} · cut order {m.dye.cut} · shade {m.dye.code} · received {m.lastIn}</div>}
      <Sect T={T} right={<Meta T={T}>accounts voucher on each row</Meta>}>Stock ledger</Sect>
      {[[m.lastIn, m.dye ? 'Dye receive · ' + m.dye.cut : 'Inward · GRN-04' + (m.id.slice(1) + 10), '+' + (m.dye ? m.stock : Math.round(m.stock * .6)), m.unit, 'OE/PI/41'], ['04/09/26', 'Issue · PO-1187 · Embroidery', '−10', m.unit, 'OE/MI/58'], ['26/08/26', 'Issue · PO-1187 · Embroidery', '−12.5', m.unit, 'OE/MI/52']].map((r, i) => <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 8, height: 32, borderTop: `1px solid ${T.line}`, fontFamily: T.fontUI, fontSize: 12 }}><Meta T={T}>{r[0]}</Meta><span style={{ flex: 1, minWidth: 0, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{r[1]}</span><Mono T={T} size={10} weight={500} color={T.ink3}>{r[4]}</Mono><span style={{ fontWeight: 600, color: r[2][0] === '+' ? T.ok : T.ink }}>{r[2]} {r[3]}</span></div>)}
      <Sect T={T}>Used in</Sect>
      <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>{['2798', '6002', '4566'].slice(0, Math.max(1, m.used % 4)).map(c => <span key={c} className="press" style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: '3px 8px 3px 3px', borderRadius: 999, background: T.chipBg, fontFamily: T.fontUI, fontSize: 11.5 }}><Thumb T={T} d={PR_D(c)} w={22} h={26} r={6} /><span style={{ fontFamily: T.fontDisplay, fontSize: 14, fontWeight: 600 }}>{c}</span></span>)}</div>
      <span style={{ flex: 1 }} />
      <div style={{ display: 'flex', gap: 6, alignItems: 'center' }}><OutBtn T={T} small icon="shopping-cart">Raise PO</OutBtn><OutBtn T={T} small icon="git-branch">Add to a recipe</OutBtn><OutBtn T={T} small icon="printer">Label</OutBtn><span style={{ flex: 1 }} /><Meta T={T}>Dispatch › Stock › Material</Meta></div>
    </div>
  </PPane>;
}
