/* the BOM grid for one colour */
function BomGrid({ T, colour = 'Sky', code = '2798', missingOnly }) {
  const seq = PR_RECIPE.seq; const rows = PR_RECIPE.rows.filter(r => r.scope === 'all' || r.scope === colour);
  const Cell = ({ on, dis, dim }) => <span style={{ width: 96, flex: 'none', display: 'grid', placeItems: 'center', opacity: dim ? .35 : 1 }}><span className={dis ? undefined : 'press'} style={{ width: 18, height: 18, borderRadius: 5, background: on ? T.ink : dis ? T.chipBg : 'transparent', border: `1.5px solid ${on ? T.ink : dis ? 'transparent' : T.line2}`, color: T.bg, display: 'grid', placeItems: 'center', opacity: dis ? .5 : 1 }}>{on && <Ic name="check" size={12} sw={3} />}</span></span>;
  const head = <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '6px 12px', borderBottom: `1px solid ${T.line}` }}><span style={{ width: 24, flex: 'none' }}><span style={{ width: 16, height: 16, borderRadius: 5, background: T.ink, color: T.bg, display: 'grid', placeItems: 'center' }}><Ic name="check" size={10} sw={3} /></span></span><span style={{ flex: 1, fontFamily: T.fontUI, fontSize: 10, letterSpacing: '.06em', textTransform: 'uppercase', color: T.ink3 }}>Materials list · tick = in this colour</span><span style={{ width: 90, flex: 'none', textAlign: 'right', fontFamily: T.fontUI, fontSize: 10, letterSpacing: '.06em', textTransform: 'uppercase', color: T.ink3 }}>Avg / pc</span><span style={{ width: 40, flex: 'none', fontFamily: T.fontUI, fontSize: 10, letterSpacing: '.06em', textTransform: 'uppercase', color: T.ink3 }}>Unit</span>{seq.map((p, i) => <span key={p} style={{ width: 96, flex: 'none', textAlign: 'center', fontFamily: T.fontUI, fontSize: 10, letterSpacing: '.06em', textTransform: 'uppercase', color: p === PR_RECIPE.final ? T.ink : T.ink3, fontWeight: p === PR_RECIPE.final ? 600 : 400, opacity: missingOnly && p !== 'Stitching' ? .35 : 1 }}>{i + 1} · {p}</span>)}</div>;
  const row = (left, avg, unit, cells, k, tint, inCol = true) => <div key={k} style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '2px 12px', borderTop: `1px solid ${T.line}`, background: tint || 'transparent' }}><span style={{ width: 24, flex: 'none' }}><span style={{ width: 16, height: 16, borderRadius: 5, background: inCol ? T.ink : 'transparent', border: `1.5px solid ${inCol ? T.ink : T.line2}`, color: T.bg, display: 'grid', placeItems: 'center' }}>{inCol && <Ic name="check" size={10} sw={3} />}</span></span><span style={{ flex: 1, minWidth: 0, overflow: 'hidden', whiteSpace: 'nowrap', textOverflow: 'ellipsis' }}>{left}</span><span style={{ width: 90, flex: 'none', textAlign: 'right' }}><span style={{ display: 'inline-block', width: 58, height: 22, lineHeight: '20px', borderRadius: 7, border: `1px solid ${T.line2}`, textAlign: 'center', fontFamily: T.fontUI, fontSize: 12, fontWeight: 600 }}>{avg}</span></span><span style={{ width: 40, flex: 'none', fontFamily: T.fontUI, fontSize: 11.5, color: T.ink2 }}>{unit}</span>{cells}</div>;
  const count = p => rows.filter(r => r.to.includes(p)).length + (PR_RECIPE.wips.find(x => x[1] === p) ? 1 : 0);
  return <div style={{ borderRadius: 16, border: `1px solid ${T.line}`, background: T.surface, overflow: 'hidden' }}>
    {head}
    {rows.map((r, i) => { const m = prMat(r.m); return row(<span style={{ display: 'inline-flex', alignItems: 'center', gap: 8 }}><Swatch m={m} w={22} h={24} r={6} /><span style={{ fontFamily: T.fontUI, fontSize: 12.5 }}>{prMatName(m)} <Meta T={T}>{m.code}{m.dye ? ' · dye wip' : ''}{r.dual ? ' · 2nd use' : ''}{!m.dye && m.name === 'Mono net' && colour === 'Peach' ? ' · undyed · dye lot DC-0035 due 15/09' : ''}</Meta></span></span>, r.avg, r.unit, seq.map(p => <Cell key={p} on={r.to.includes(p)} dim={missingOnly && p !== 'Stitching'} />), i); })}
    <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '6px 12px', borderTop: `1px solid ${T.line}`, background: T.bg2 }}><span style={{ fontFamily: T.fontUI, fontSize: 10, letterSpacing: '.06em', textTransform: 'uppercase', color: T.ink3 }}>WIPs list · auto per process · each feeds one later process</span><span style={{ flex: 1 }} /><span style={{ width: 96, flex: 'none', textAlign: 'center', fontFamily: T.fontUI, fontSize: 10, letterSpacing: '.06em', textTransform: 'uppercase', color: T.ink3 }}>finished good</span></div>
    {seq.map((p, i) => { const w = PR_RECIPE.wips.find(x => x[0] === p); const last = p === PR_RECIPE.final; return row(<span style={{ display: 'inline-flex', alignItems: 'center', gap: 8 }}><span style={{ width: 22, height: 24, borderRadius: 6, background: T.chipBg, display: 'grid', placeItems: 'center' }}><Ic name="layers" size={12} color={T.ink2} /></span><Mono T={T} size={12} weight={500}>{last ? `${code}_${colour.toLowerCase()}` : prWipName(p, code, colour)}</Mono>{last && <Pill T={T} tone="muted" small>finished good</Pill>}</span>, 1, 'pc', seq.map((q, k) => <Cell key={q} on={w && w[1] === q} dis={k <= i} dim={missingOnly && q !== 'Stitching'} />), 'w' + i, last ? T.accentSoft : undefined); })}
    <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '6px 12px', borderTop: `1px solid ${T.line}` }}><span style={{ width: 24 }} /><Meta T={T} style={{ flex: 1 }}>a tick is the setting · the BOMs pane shows the result live</Meta><span style={{ width: 130 }} />{seq.map(p => { const n = count(p); const set = n > 0 && !(colour === 'Peach' && p === 'Stitching'); return <span key={p} style={{ width: 96, flex: 'none', display: 'grid', placeItems: 'center' }}>{set ? <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4, fontFamily: T.fontUI, fontSize: 11, color: T.ok }}><Ic name="check" size={12} sw={2.5} />BOM set · {n}</span> : <OutBtn T={T} small style={{ height: 26, padding: '0 9px', fontSize: 11 }}>Set BOM</OutBtn>}</span>; })}</div>
  </div>;
}
const ColourTabsRow = ({ T, on, copyFrom, right }) => <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 8 }}>{PR_RECIPE.colours.map(c => <T.Chip key={c} on={c === on} outline={c !== on} style={{ height: 32 }}><Dot n={c} s={8} />{c}{c === 'Peach' && <Pill T={T} tone="warn" small>1 missing</Pill>}</T.Chip>)}<OutBtn T={T} small icon="copy">Copy {copyFrom || 'Sky'} to the other colours</OutBtn><span style={{ flex: 1 }} />{right}</div>;
